 if(sourceId==null||sourceId===''||(state.doubleEntryJournal||[]).some(e=>e.sourceKey===sourceType+':'+sourceId&&!e.reversed))throw Error('R359 قيد مكرر أو معرف مفقود');if(ls.length<2||ls.reduce((s,l)=>s+cents(l.debitUSD)-cents(l.creditUSD),0)!==0)throw Error('R359 قيد غير متوازن');return {sourceType,sourceId,reference:ref||x.ref||x.number,date:when||x.date,description:op+' '+(x.ref||x.number||''),lines:ls,r359Kind:kind,r359DocumentId:String(x.id),r359HistoricalBaseReview:review}}
function post(p){if(!p)return;const e=window.pos7PostJournalEntry(p);for(const k of ['r359Kind','r359DocumentId','r359HistoricalBaseReview'])e[k]=p[k];return e}
// Only these infrequent operations, not invoice creation or edit hot path.
