function invoiceCash(inv){const cur=String(inv.currency||'USD').toUpperCase(),ps=Array.isArray(inv.paymentParts)?inv.paymentParts.filter(x=>num(x.amount)>0):[],cs=Array.isArray(inv.changeParts)?inv.changeParts.filter(x=>num(x.amount)>0):[];if(!ps.length&&num(inv.paid??0)>0){if(!inv.paymentSource)throw Error('R359 مصدر الدفع التاريخي غير مثبت');ps.push({account:inv.paymentSource,currency:cur,amount:inv.paid})}const r=rate(inv);for(const p of [...ps,...cs])leg(p,r,1);return {ps,cs}}
